INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-1-invu', 'Framework Gravity INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('INVU no es un POS, es un Ecosistema', 'INVU POS no es simplemente un sistema de facturación o un software de punto de venta. Es un ecosistema operativo completo diseñado para centralizar, automatizar y potenciar todas las áreas críticas de un negocio comercial: ventas, inventarios, producción, marketing, fidelización y análisis de datos. Funciona como el cerebro digital de la operación, conectando sucursales, equipos, clientes y procesos en una sola plataforma sincronizada. Cuando un vendedor entiende esto, deja de vender un "software" y comienza a vender una solución de transformación digital.', 'Un vendedor llega a un restaurante con 3 sedes y el dueño le dice: "Ya tengo un POS que me factura". El vendedor responde: "No estoy aquí para venderte otro POS. Estoy aquí para mostrarte cómo puedes centralizar tus 3 sedes en un solo panel, sincronizar tu inventario en tiempo real, y ver reportes consolidados de rentabilidad por sede desde tu celular. INVU no es un POS, es el cerebro digital de tu operación." El dueño, que antes veía a INVU como un reemplazo de su sistema, ahora lo ve como una herramienta de crecimiento.', 1),
('La Diferencia entre Característica y Beneficio', 'Una característica es lo que el sistema tiene. Un beneficio es lo que el cliente gana. El vendedor de nivel básico enumera características; el vendedor de nivel Gravity traduce cada característica en un beneficio que resuelve un dolor específico del cliente. La fórmula es: "Esto significa que...", "Por qué importa...", "Qué problema evita...", "Qué beneficio genera..."', 'Característica: "INVU tiene facturación electrónica nativa."  
Beneficio: "Eso significa que no pagas S/89-149 mensuales a Nubefact o Efact. Este ahorro mensual ya cubre gran parte de la diferencia de precio con otros sistemas. Además, tu facturación está integrada con el inventario, así que cada factura actualiza tu stock automáticamente."  
El cliente no compra la característica; compra el ahorro y la integración.', 2),
('El Diagnóstico es el Primer Paso (y el más importante)', 'El primer paso en cualquier interacción comercial es escuchar más de lo que se habla. Hacer preguntas abiertas para entender la operación actual del cliente, sus dolores, objetivos y limitaciones. No se trata de vender INVU, se trata de entender al negocio para luego ofrecer la solución que realmente necesita. Si no diagnosticas, estás vendiendo a ciegas.', 'Un vendedor inicia una llamada: "Hola, soy de INVU. Permíteme hacerte unas preguntas para entender tu negocio: ¿Cuántas sedes tienes? ¿Qué sistema usas hoy para facturar e inventario? ¿Cómo manejas la facturación electrónica? ¿Tienes recetas costeadas? ¿Usas delivery?" Luego de 5 minutos de preguntas, el vendedor identifica que el cliente tiene 3 sedes, paga Nubefact aparte y no tiene control de inventario centralizado. Ahora sabe exactamente qué dolor atacar y qué módulos de INVU mostrar. Sin el diagnóstico, habría hecho una demo genérica y perdido la oportunidad.', 3),
('Las 7 Preguntas que Todo Vendedor Debe Hacer', 'Existen 7 preguntas de diagnóstico que revelan si el cliente califica, qué setup aplicar, qué licencias cotizar y cuál es el argumento de valor principal. Estas preguntas son la brújula del vendedor. Sin ellas, estás navegando sin mapa.', 'En una reunión con un dueño de restaurante, el vendedor hace las 7 preguntas en 5 minutos:  
"¿Cuánto facturan al mes y cuántas sedes tienen?" → S/120,000, 3 sedes.  
"¿Qué sistema usan hoy y qué los hace cambiar?" → POS básico, no centraliza.  
"¿Cómo emiten su factura electrónica?" → Nubefact, S/120/mes por sede.  
"¿Tienen recetas costeadas y control de inventario?" → No, operan a ciegas.  
"¿Cuántas cajas necesitan por sucursal?" → 2 por sede.  
"¿Manejan delivery propio o solo apps?" → Rappi, pagan 25% comisión.  
"¿Quién toma la decisión y cuándo necesitan estar arriba?" → El dueño, en 2 semanas.  
Con estas respuestas, el vendedor sabe que necesita cotizar INVU Central + 3 licencias Sucursal + KDS + QR + Loyalty, y que el argumento principal será centralización y ahorro en PSE.', 4),
('El Poder del Onboarding Consultivo', 'INVU no solo enseña a usar el sistema; ayuda al cliente a montar una operación limpia y rentable desde el día del go live. Se trabaja con el dueño para que el sistema refleje un negocio rentable: menú completo categorizado, recetas con costo por plato, materia prima y proveedores, métodos de pago y propinas, roles y permisos, descuentos y promociones, reportes y dashboards. Desde el primer ticket, el cliente ve su margen real, su inventario y su costo por plato. Esto transforma al vendedor en un consultor de confianza.', 'Un vendedor le dice al dueño: "No solo te enseñamos a usar el sistema. Te ayudamos a montar tu operación para que sea rentable desde el día uno. Seteamos tu menú con recetas y costos reales, tu materia prima y proveedores. Así, cuando vendas un plato, sabes exactamente cuánto estás ganando. No más operar a ciegas." El dueño, que nunca había visto el margen real de sus platos, percibe a INVU como un socio, no como un proveedor.', 5),
('El Valor del Soporte Local 24/7', 'INVU tiene equipo de soporte en Perú, en horario Perú, con atención por WhatsApp directo a un humano, soporte remoto y en sitio. Cuando el sistema falle un viernes a las 9pm, el cliente llama a un equipo en Perú que responde en minutos. Esto no es un lujo; es una necesidad crítica para la continuidad del negocio.', 'Un cliente objeta: "¿Y si el sistema falla un viernes a las 9pm?" El vendedor responde: "Excelente pregunta. Con INVU, llamas a nuestro equipo en Perú, por WhatsApp, y te responde un humano. No bots, no formularios, no espera de 48 horas. La competencia te da un ticket que responden en 24-48 horas desde otro país. INVU te da un humano que habla tu idioma y está en tu mismo huso horario. Te paso el WhatsApp del equipo técnico antes de firmar." El cliente se siente seguro.', 6),
('El Framework Gravity – 5 Pasos para Vender con Autoridad', 'El Framework Gravity es un proceso de 5 pasos que convierte al vendedor en un asesor de confianza: Diagnóstico (escucha), Educación (explica la lógica), Comparación (con datos concretos), Construcción de Valor (cuantifica beneficios), Cierre (pregunta que avanza el proceso). No es un guion rígido; es una secuencia lógica que guía al cliente desde la duda hasta la decisión.', 'Un vendedor aplica Gravity en una llamada de 20 minutos:  
Diagnóstico (5 min): Hace las 7 preguntas.  
Educación (5 min): "INVU incluye FE nativa, así que te ahorras S/360/mes en Nubefact."  
Comparación (5 min): "Tu costo actual es S/1,110/mes. Con INVU, S/1,862/mes, pero incluye centralización y fidelización."  
Construcción de Valor (5 min): "Si reducimos tus mermas en un 2%, ahorras S/2,400/mes. La inversión se paga sola."  
Cierre: "¿Qué información necesitas para tomar la decisión?" El cliente pide la cotización.', 7),
('El Protocolo Gravity para Manejar Objeciones', 'Toda objeción es una oportunidad para construir valor. El Protocolo Gravity tiene 5 pasos: Escucha/Valida (reconoce la preocupación), Diagnostica (pregunta para entender el origen), Reencuadra (reformula como oportunidad), Micro-cierre (obtén un pequeño compromiso), Cierre (avanza al siguiente paso). No es una batalla; es una danza.', 'Cliente: "Es caro."  
Vendedor:  
Valida: "Entiendo que el precio es una consideración importante."  
Diagnostica: "¿Qué es lo que te parece caro exactamente, el setup o las licencias mensuales?"  
Reencuadra: "Cuando sumas lo que pagas por Nubefact (S/120/mes), soporte (S/80/mes) y sistemas separados, el costo real de la competencia es S/450/mes. INVU es S/350/mes todo incluido."  
Micro-cierre: "¿Te parece si hacemos el cálculo con tus números actuales?"  
Cierre: "¿Qué día te acomoda para la demo?"', 8),
('La Comparación con Datos, no con Opiniones', 'El vendedor debe comparar INVU con las alternativas del mercado desde una posición de autoridad, no defensiva. Se explica qué ofrecen los sistemas básicos, dónde fallan y por qué INVU es superior en integración, escalabilidad, soporte y costo a largo plazo. La comparación se hace con datos concretos, no con opiniones.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo (Nubefact/Efact) y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia te cobra por actualizaciones, por visitas técnicas, y no incluye módulos de marketing ni e-commerce sin comisiones. Esa diferencia de S/100 al mes es el 0.2% de tu facturación. ¿Vale la pena ahorrar S/100 al mes a cambio de perder centralización, integración y soporte 24/7?"', 9),
('El Ritmo del Vendedor Ganador (Hunters)', 'El Hunter ganador mantiene un ritmo de: 15 visitas/semana, 30 interacciones/mes, 10 reuniones con decisores/mes, 5 demos/mes, 2-3 cierres/mes. El ingreso del Hunter está directamente ligado a su esfuerzo. No hay atajos. La prospección constante y el registro meticuloso en CRM son la base del éxito.', 'Un Hunter tiene un mes de 4 semanas. Se fija metas diarias: 3 visitas a restaurantes, 1 interacción por teléfono, 1 reunión con decisor. Al final de la semana, tiene 15 visitas y 5 reuniones. Al mes, 60 visitas y 20 reuniones. De esas, hace 5 demos y cierra 3 ventas. Su ingreso: base (S/2,958) + comisiones (S/490) + bono (S/850) + MRR (S/252) = S/4,550. El esfuerzo se traduce en dinero. El que no visita, no vende.', 10),
('La Escalera Base – Protección y Motivación', 'El programa Hunters tiene una escalera base que protege al vendedor en sus primeras ventas: 1 venta = S/1,258, 2 ventas = S/2,108, 3 ventas = S/2,958. Esto permite al vendedor estabilizarse y enfocarse en construir mercado, sin la presión del "todo o nada". Además, una venta grande (setup S/15,000+) vale por 3 ventas, reconociendo el esfuerzo de cerrar cuentas grandes.', 'Un Hunter nuevo cierra su primera venta en el mes 1. Cobra S/1,258 (S/850 + S/408 de viáticos). No es un sueldo enorme, pero es suficiente para que no se desmotive. En el mes 2, cierra 2 ventas: S/2,108. En el mes 3, cierra 3 ventas: S/2,958. Ya estabilizado, en el mes 4 cierra 5 ventas: base S/2,958 + comisiones + bono S/850 = S/4,298. La escalera lo llevó desde la incertidumbre a un ingreso sólido.', 11),
('La Comisión MRR – Ingresos Pasivos que se Construyen', 'Desde la cuarta venta, el Hunter gana 3% MRR mensual sobre las licencias activas de sus clientes durante 12 meses. Cada cliente que trae le paga mes a mes, construyendo una "cola" de ingresos que se acumula. Después de un año con 10 clientes, el Hunter recibe el 3% de las licencias de esos 10 clientes mensualmente sin hacer nada adicional. Esto es lo que convierte un ingreso de "cazador" en un ingreso de "agricultor".', 'Un Hunter cierra 2 clientes al mes durante 6 meses = 12 clientes. Cada cliente paga un promedio de S/700/mes en licencias. El 3% de S/700 es S/21/mes por cliente. Después de 6 meses, el Hunter tiene una cola MRR de 12 clientes × S/21 = S/252/mes. Al año, con 24 clientes, la cola MRR es S/504/mes. Ese dinero llega mes a mes sin que el Hunter haga nada adicional. La cola MRR es la jubilación del vendedor.', 12),
('La Visita Técnica como Herramienta de Ventas', 'La visita técnica no es un simple trámite de instalación. Es una herramienta estratégica de consultoría que se sitúa entre la demo y la cotización, permitiendo al Hunter demostrar profesionalismo, identificar necesidades adicionales de hardware y garantizar una implementación exitosa. La visita técnica valida la red, el hardware y la distribución del local, y genera un informe que el Hunter usa para justificar la inversión total (software + hardware). Es un diferenciador clave frente a la competencia.', 'Un Hunter agenda la visita técnica para un restaurante. El especialista de INVU descubre que el WiFi no llega a la cocina, que la impresora es obsoleta, y que el internet es coaxial (lento). El informe técnico recomienda: router Mesh WiFi, impresora 3nStar RPT004, y fibra óptica. El Hunter incluye esto en la cotización, sumando S/1,500 en hardware adicional. Su comisión (10% desde la 4ª venta) aumenta en S/150. Además, el cliente tiene certeza de que el sistema funcionará sin problemas. El Hunter cierra con autoridad.', 13),
('La Regla de "Venta Grande Vale por Tres"', 'Si el Hunter cierra una venta cuyo setup facturado suma S/15,000 o más (por ejemplo, una cadena de varias sedes), esa venta cuenta como 3 para la escalera base. Esto reconoce que cerrar una cuenta grande requiere tanto o más esfuerzo que cerrar tres pequeñas, y alinea el incentivo del Hunter con el valor del negocio.', 'Un Hunter cierra una cadena de 5 sedes con un setup de S/18,000. Aunque es una sola transacción, cuenta como 3 ventas para la escalera base. El Hunter recibe la base completa de S/2,958 en su liquidación, más las comisiones de setup desde la primera venta (10% de S/18,000 = S/1,800). En una sola transacción, el Hunter gana más que en 3 transacciones pequeñas. El sistema premia ir por lo grande.', 14),
('El Bono Trimestral – La Recompensa a la Consistencia', 'El Bono Trimestral de S/3,400 se otorga cuando el Hunter mantiene un promedio de 10 ventas/mes (o 30 en el trimestre). No es un bono por un mes bueno; es un bono por consistencia. Esto incentiva al Hunter a no bajar el ritmo y a mantener su pipeline lleno durante todo el trimestre.', 'Un Hunter tiene un trimestre con 10, 9 y 11 ventas. Promedio: 10 ventas/mes. Gana el bono de S/3,400, que se suma a su base y comisiones. Ese mes extra de S/3,400 puede representar el 40-50% de su ingreso mensual. La consistencia no solo genera ingresos estables, sino que tiene una recompensa extraordinaria.', 15),
('El ROI – Cómo Justificar la Inversión con Números', 'El valor no está en el precio, está en lo que el cliente gana. El vendedor debe cuantificar los beneficios: horas de trabajo ahorradas, errores de inventario reducidos, ventas incrementadas, control financiero consolidado y tranquilidad. Calcular el retorno de inversión (ROI) en meses es la herramienta más poderosa para cerrar.', 'Un restaurante factura S/50,000/mes. Con INVU, reduce mermas en un 2% (S/1,000/mes), ahorra S/120/mes en PSE externo, y aumenta ventas en un 5% con QR y Loyalty (S/2,500/mes). Ahorro total: S/3,620/mes. La inversión en INVU es S/350/mes. El ROI es del 934%. El retorno de inversión se da en menos de 1 mes. Con estos números, el cliente no puede decir "es caro".', 16),
('Los 3 Tipos de Clientes y Cómo Venderles', 'Existen 3 tipos de clientes: el que no sabe que necesita INVU (hay que educar), el que sabe que necesita pero duda (hay que comparar), y el que está listo para comprar (hay que cerrar). El vendedor debe identificar en qué etapa está cada cliente y adaptar su estrategia. No se vende igual a un cliente que no sabe que existe la facturación electrónica nativa que a uno que ya la conoce.', 'Cliente tipo 1 (no sabe): "¿Sabías que la SUNAT exige facturación electrónica y que la mayoría de POS te cobran aparte por eso? INVU ya la incluye."  
Cliente tipo 2 (sabe pero duda): "Has visto otras opciones. ¿Qué te ofrecen que INVU no tenga? Yo te muestro la diferencia."  
Cliente tipo 3 (listo): "¿Qué información necesitas para firmar? ¿Te parece si empezamos con el setup la próxima semana?"', 17),
('El Rol del Vendedor como Asesor de Confianza', 'El vendedor de Gravedad Cero no solo vende INVU, sino que se convierte en un asesor de confianza del cliente. Controla toda la conversación desde el diagnóstico hasta el cierre sin perder el control. El cliente siente que está tomando la decisión, pero en realidad el vendedor ha guiado cada paso. El cierre no es forzado; es el resultado natural de una conversación donde no comprar INVU parece una mala decisión comercial.', 'Un cliente dice: "Lo voy a pensar."  
El vendedor responde: "Es normal. Lo que muchos clientes me dicen es que después de pensarlo, se dan cuenta de que el costo de no tener control es mayor que la inversión. Cada mes que postergas, estás pagando S/120 a Nubefact, perdiendo S/2,000 en mermas y S/2,500 en comisiones de delivery. Pensarlo cuesta dinero. ¿Qué información te falta para decidir? Si es algo que puedo resolver hoy, lo resolvemos. Si no, te paso un caso de un cliente parecido al tuyo." El cliente, que estaba a punto de irse, se queda y pide la cotización.', 18),
('El Pitch de 30 Segundos que Enamora', 'El pitch de 30 segundos es la herramienta que engancha al cliente desde el primer momento. Debe ser breve, contundente y conectar con el dolor del cliente. No es una lista de características; es una declaración de valor que deja al cliente con una sola pregunta: "¿Cómo lo vemos?"', '"INVU POS es el sistema operativo que usan más de 5,000 restaurantes en Latam. A diferencia de los POS locales, incluimos facturación electrónica nativa, llegamos llave en mano y te dejamos el restaurante operando desde el día uno. No vendemos un POS, vendemos una operación rentable."  
El cliente, que ha estado batallando con su POS actual, dice: "¿Cómo lo vemos?" El vendedor ya tiene la reunión.', 19),
('Los Errores que Matan la Venta', 'Hay 6 errores comunes que el vendedor debe evitar: (1) Hablar de precio antes de crear valor, (2) No diagnosticar, (3) No explicar las diferencias técnicas, (4) No comparar, (5) No cerrar, (6) Hacer descuentos sin justificación. Estos errores convierten al vendedor en un "proveedor más" y lo sacan de la categoría de "asesor de confianza".', 'Un cliente pregunta: "¿Cuánto cuesta?"  
El vendedor novato responde: "S/350/mes."  
El cliente dice: "Es caro." Se va.  
El vendedor experto responde: "El costo depende de tus necesidades. Permíteme hacerte algunas preguntas para entender tu operación y darte una cotización precisa. ¿Cuántas sedes tienes? ¿Qué sistema usas hoy?" El cliente se queda, responde, y el vendedor construye valor antes de dar el precio. La venta avanza.', 20),
('Multiplataforma – Libertad para el Cliente', 'INVU funciona en iOS, Android y Windows, permitiendo operar desde tablets, computadoras o dispositivos móviles. Esto da al negocio la libertad de elegir el equipo que mejor se adapte a su operación, sin estar atado a un proveedor específico. El vendedor debe comunicar esto como un ahorro y una ventaja, no como un dato técnico.', '"No te vamos a decir qué dispositivo comprar. INVU funciona en iOS, Android y Windows. Usa la tablet que ya tienes, la computadora que prefieras, o el dispositivo que elijas. La libertad de elegir es parte de nuestro valor. Y con tablets, tu personal puede tomar pedidos en cualquier lugar del local." El cliente, que ya tiene tablets, se siente aliviado de no tener que comprar hardware nuevo.', 21),
('El Upgrade de los Programas de Referidos a Partners', 'El programa de Partners es una evolución del programa de Referidos. Mientras el referido cobra una comisión fija (S/500, S/1,000, S/1,500), el Partner cobra el 8% del valor total del primer año del cliente (setup + 12 mensualidades), pagado en tres tramos. El Partner tiene un incentivo para traer clientes más grandes, porque su comisión crece proporcionalmente. El referido es para contactos ocasionales; el Partner es para profesionales que quieren monetizar su red de contactos de manera recurrente.', 'Un contador refiere a un cliente de 1 sede: comisión S/532 (8% de S/6,650).  
Si el mismo contador refiere una cadena de 10 sedes: comisión S/6,057 (8% de S/75,708).  
El contador entiende que su red de contactos de clientes grandes vale mucho más. Se convierte en Partner y enfoca sus esfuerzos en las cuentas grandes.', 22),
('El Registro en CRM – Lo que no está, no existe', 'El registro en CRM es la disciplina que separa al vendedor profesional del aficionado. Cada visita, reunión, demo y oportunidad debe estar registrada. Los viáticos se pagan solo con evidencia de gestiones. El CRM es la herramienta que convierte el esfuerzo en resultado y permite a la empresa apoyar al vendedor con datos reales.', 'Un Hunter hace 15 visitas a la semana, pero no las registra. Al final del mes, no puede demostrar su esfuerzo para recibir viáticos. Además, pierde seguimiento de oportunidades porque no las anotó. Otro Hunter registra cada visita, cada reunión y cada promesa en el CRM. La empresa ve su esfuerzo, le paga sus viáticos, y le da seguimiento a sus oportunidades. El Hunter que registra, triunfa.', 23),
('La Reutilización de Hardware – Confianza y Ahorro', 'Durante la visita técnica, el especialista de INVU evalúa el hardware existente del cliente (impresoras, lectores, cajones, tablets) y recomienda reutilizar todo lo que sea compatible. Esto ahorra dinero al cliente y construye confianza. El vendedor debe comunicar esto como un gesto de honestidad, no como una concesión.', 'El cliente dice: "No quiero comprar impresoras nuevas."  
El vendedor responde: "No vamos a obligarte a comprar hardware nuevo si lo que tienes funciona. Nuestro especialista va a revisar tus impresoras, lectores y cajones, y te va a recomendar reutilizar todo lo que sea compatible. Así ahorras en la inversión inicial y solo compras lo que realmente necesitas." El cliente confía en el vendedor porque no le está vendiendo algo que no necesita.', 24),
('El Router 4G de Respaldo – Seguro de Continuidad', 'Para comercios con alta demanda de delivery e integraciones, INVU recomienda un router con chip 4G de respaldo que asegura operación continua si el internet principal falla. El vendedor debe vender esto como un seguro, no como un lujo.', '"Tu internet puede fallar, pero tu negocio no debe detenerse. Por eso recomendamos un router con chip 4G de respaldo. Si el internet principal se cae, el sistema cambia automáticamente al respaldo y sigues operando sin perder una venta. Es tu seguro de continuidad." El cliente, que ha perdido ventas por cortes de internet, ve el valor inmediato y acepta la recomendación.

# PÍLDORAS DE CONOCIMIENTO - INVU POS LATINOAMÉRICA', 25),
('INVU es el Sistema Operativo del Comercio Latinoamericano', 'INVU POS no es un software importado y adaptado a la región. Nació en Latinoamérica y entiende su esencia: el acento, la forma de cobrar, la manera de atender, las ganas de crecer. Mientras que los sistemas extranjeros imponen lógicas de otros mercados, INVU habla el idioma del comercio latinoamericano. Cuando un vendedor comunica esto, no está vendiendo un sistema; está vendiendo una solución que respeta y potencia la identidad del negocio del cliente.', 'Un vendedor en Colombia le dice al dueño de un restaurante: "INVU no es un sistema diseñado en otro continente y traducido al español. Nació en Latinoamérica, entiende cómo se vive, se vende y se sueña aquí. Sabe que cada país tiene su acento, su forma de cobrar, su manera de atender. INVU habla tu idioma, no solo en castellano, sino en el idioma de tu negocio." El cliente, que ha probado sistemas importados que no entienden su realidad, se siente escuchado y confía.', 26),
('La Interfaz que No Obliga a Pensar, Permite Avanzar', 'INVU no obliga a leer manuales eternos ni a navegar en pantallas confusas. Todo está donde debe estar: menú personalizado, CRM de clientes, imágenes del menú, buscador de producto, divisor de cuentas al instante, KDS sin retrasos, control de ingreso de colaboradores y mapa de mesas. La interfaz no obliga a pensar, permite avanzar. Para el vendedor, esto significa que el cliente no tendrá una curva de aprendizaje larga; el sistema es intuitivo desde el día uno.', 'Un cliente objeta: "Mis empleados son mayores, no saben usar tecnología." El vendedor responde: "INVU está diseñado para que cualquiera lo use sin entrenamiento extenso. Todo está donde debe estar: el menú con imágenes, el buscador que encuentra cualquier producto en segundos, el divisor de cuentas que hace el cálculo automático. Tu personal no tiene que pensar en cómo funciona el sistema; solo tiene que usarlo. La interfaz no obliga a pensar, permite avanzar."', 27),
('Integración Total vs. Caos de Múltiples Sistemas', 'Mientras otros sistemas obligan a manejar cinco plataformas distintas (POS, inventario, delivery, ecommerce, facturación), INVU integra todo en un solo lugar. Nada de saltar entre sistemas, nada de duplicar trabajo. INVU no cambia el flujo del negocio, lo mejora. El vendedor debe comunicar que la integración no es un lujo; es una necesidad para operar eficientemente en el entorno latinoamericano, donde el tiempo y los recursos son limitados.', '"No necesitas cinco sistemas diferentes para manejar tu negocio. Con INVU, delivery, inventario, ecommerce y facturación están en un solo lugar. Una venta en tu tienda física se refleja en tu inventario y en tus reportes sin que tengas que hacer nada. Tu operación se simplifica, no se complica. Deja de saltar entre sistemas y empieza a controlar todo desde un solo panel."', 28),
('Flexibilidad de Hardware – Libertad para Elegir', 'INVU funciona sin problemas en iOS, Android y Windows, permitiendo operar desde tablets, computadoras o dispositivos móviles. Esto da al negocio la libertad de elegir el equipo que mejor se adapte a su operación, sin estar atado a un proveedor específico. El vendedor debe comunicar esto como un ahorro significativo: no hay que comprar hardware caro y específico; se puede usar lo que ya se tiene.', '"No te vamos a decir qué dispositivo comprar. INVU funciona en iOS, Android y Windows. Usa la tablet que ya tienes, la computadora que prefieras, o el dispositivo que elijas. La libertad de elegir es parte de nuestro valor. Y con tablets, tu personal puede tomar pedidos en cualquier lugar del local. No estás atado a un proveedor ni a un hardware costoso."', 29),
('El Ecosistema que Fideliza Clientes', 'INVU no solo procesa ventas; ayuda a que los buenos clientes siempre vuelvan con tarjetas perforadas y wallet digital, donde cada visita suma, cada compra deja huella y cada cliente siente que vale la pena regresar. El vendedor debe mostrar que INVU no es solo una herramienta de facturación, sino una máquina de retención de clientes.', '"Los buenos clientes siempre vuelven con INVU. El sistema de fidelización integra tarjetas perforadas y wallet digital: cada compra suma, el cliente ve su saldo en su celular, y tú ves cómo aumenta la recurrencia. El cliente gana, el negocio también. No pierdas más clientes que compran una vez y no regresan. INVU los trae de vuelta."', 30),
('El POS que No Hace Esperar al Cliente', 'El POS de INVU está diseñado para la velocidad: menú personalizado, imágenes de productos, buscador, divisor de cuentas instantáneo. En Latinoamérica, donde las filas pueden ser largas y los clientes impacientes, la velocidad de atención es un diferenciador crítico. Un vendedor debe comunicar que INVU reduce el tiempo de atención y aumenta la satisfacción del cliente.', '"Con INVU, tu personal no tiene que pensar en cómo funciona el sistema. Todo está donde debe estar: el menú con imágenes, el buscador que encuentra cualquier producto en segundos, el divisor de cuentas que hace el cálculo automático. Tu equipo avanza rápido, las filas se mueven, y tus clientes no esperan. Menos estrés, más ventas."', 31),
('El KDS – El Fin del Caos en la Cocina', 'El KDS de INVU sincroniza pedidos en tiempo real, con alertas de comanda, reportes de tiempos y organización visual de órdenes. En cualquier restaurante latinoamericano, el caos en cocina es el principal generador de errores y demoras. El KDS elimina las comandas de papel, organiza la preparación y reduce los tiempos de espera. El vendedor debe mostrar que el KDS no es un lujo; es una necesidad para cualquier negocio de alimentos.', '"El caos en cocina se acaba con INVU KDS. Los pedidos llegan organizados, con alertas claras y tiempos medidos. Tu cocina sabe exactamente qué preparar, en qué orden y en cuánto tiempo. Menos errores, más rapidez, clientes felices. El flujo de pedidos deja de ser un problema y se convierte en tu ventaja. Dile adiós a las comandas de papel perdidas."', 32),
('Datos en Tiempo Real – El Control en la Palma de la Mano', 'INVU Reportes permite acceder a ventas, movimientos y números clave en tiempo real desde cualquier parte del mundo, con IA integrada para agilizar el análisis. El dueño del negocio latinoamericano, que muchas veces no puede estar en todos sus locales, necesita este control remoto. El vendedor debe comunicar que INVU libera al dueño de la obligación de estar presente para saber qué está pasando.', '"Tu negocio no debería depender de que estés presente. Con INVU Reportes, ves tus ventas, movimientos y números clave en tiempo real desde cualquier lugar. Sin llamadas, sin esperar cierres, sin suposiciones. El control está donde estés tú. Puedes estar de viaje o en casa y saber exactamente cómo va tu operación."', 33),
('El Inventario que se Controla Solo', 'El inventario de INVU se actualiza automáticamente con cada venta, compra o ajuste. El sistema notifica cuándo hay que reabastecer y ayuda a hacer compras inteligentes. En Latinoamérica, donde las mermas y el desperdicio son fugas de dinero comunes, un inventario automático es una herramienta de rentabilidad. El vendedor debe mostrar que INVU convierte el inventario en un aliado, no en un dolor de cabeza.', '"Con INVU, tu inventario se controla solo. Cada venta lo actualiza, cada compra lo ajusta, y el sistema te avisa cuándo tienes que reabastecer. Nada de pérdidas por vencimiento, nada de quedarte sin lo que más vendes. Menos caos en el inventario, más control en tu negocio. Deja de comprar por intuición y empieza a comprar con datos."', 34),
('Los Kioskos que Venden Mientras Tú Descansas', 'Los kioskos de autoservicio de INVU permiten a los clientes ordenar directamente sin esperas, con pedidos rápidos y total precisión. El cliente arma su pedido, paga, y el sistema lo envía directo a producción. En un mercado latinoamericano donde las filas largas pueden ahuyentar clientes, el autoservicio es una ventaja competitiva. El vendedor debe mostrar que los kioskos no solo venden; venden las 24 horas sin necesidad de personal adicional.', '"Imagina que tus clientes pueden pedir sin esperar, sin filas, sin errores. Los kioskos de INVU venden por ti las 24 horas. El cliente arma su pedido, paga, y el sistema lo envía directo a producción. Tú ganas en eficiencia, ellos ganan en rapidez. Es como tener un vendedor extra que nunca se cansa."', 35),
('Ecommerce Integrado – El Canal Digital sin Comisiones', 'El ecommerce de INVU integra las ventas digitales directamente al sistema POS, con pedidos que entran limpios, inventario sincronizado y control total. Las ventas online no son un mundo aparte; se integran con el resto de la operación. Y lo mejor: el ecommerce propio de INVU no cobra comisiones. El vendedor debe comunicar que INVU permite vender por internet sin ceder el 25-30% a Rappi o PedidosYa.', '"Con INVU, tu ecommerce no es un mundo aparte. Los pedidos online entran directo al sistema, el inventario se actualiza solo, y toda la operación está sincronizada. Menos errores, menos reprocesos, más control. Un solo sistema para todo tu negocio. Y tu tienda online no paga comisiones: el 100% de la venta es para ti."', 36),
('Wallet Digital – La Fidelización que el Cliente Siente', 'INVU Loyalty incluye tarjetas perforadas digitales y wallet, donde cada visita suma, cada compra deja huella y cada cliente siente que vale la pena regresar. El sistema de fidelización está integrado al POS; no es una herramienta separada. Cada compra suma puntos automáticamente. En Latinoamérica, donde la lealtad del cliente es clave para la sostenibilidad del negocio, esta herramienta es esencial.', '"Los buenos clientes siempre vuelven con INVU. El sistema de fidelización integra tarjetas perforadas y wallet digital: cada compra suma, el cliente ve su saldo en su celular, y tú ves cómo aumenta la recurrencia. El cliente gana, el negocio también. No pierdas más clientes que compran una vez y no regresan."', 37),
('Facturación Electrónica que No Duele', 'INVU genera facturación electrónica automática, cumpliendo con requisitos legales y manteniendo la información conectada con ventas, inventarios y reportes. El comerciante no tiene que preocuparse por el proceso; el sistema lo hace automáticamente. En Latinoamérica, donde los requisitos fiscales varían por país, pero siempre son complejos, tener una facturación integrada es un alivio.', '"La facturación electrónica es necesaria, pero no tiene que ser un dolor de cabeza. INVU la genera automáticamente, la registra en ventas e inventarios, y cumple con todo lo que pide la ley. Tú sigues vendiendo, nosotros nos encargamos. No más errores, no más multas, no más procesos manuales."', 38),
('Multiplataforma – El Hardware que ya Tienes Sirve', 'INVU funciona sin problemas en iOS, Android y Windows. El negocio no está atado a un tipo de hardware específico. Puede usar tablets, computadoras o dispositivos móviles según lo necesite la operación. En Latinoamérica, donde los presupuestos son ajustados, poder reutilizar el hardware existente es un ahorro significativo.', '"No te vamos a decir qué dispositivo comprar. INVU funciona en iOS, Android y Windows. Usa la tablet que ya tienes, la computadora que prefieras, o el dispositivo que elijas. La libertad de elegir es parte de nuestro valor. Y con tablets, tu personal puede tomar pedidos en cualquier lugar del local. No estás atado a un proveedor."', 39),
('El Costo de No Tener Integración', 'Los sistemas básicos parecen baratos, pero esconden costos: sistemas separados para delivery, ecommerce, inventario y fidelización; doble gestión de datos; pérdida de tiempo de los empleados; migración forzada al crecer. El vendedor debe mostrar que el costo real de una solución fragmentada es mayor que el costo de INVU a largo plazo.', '"Un sistema básico cuesta menos el primer año, pero al segundo año necesitas integración con delivery, al tercero ecommerce y fidelización. Cada una es un sistema separado con su costo. Al cuarto año, migras y pagas dos veces por todo. INVU, con su ecosistema integrado, evita estos costos. Invierte una vez, crece sin límites."', 40),
('El ROI en el Contexto Latinoamericano', 'Un sistema POS básico en Latinoamérica tiene una vida útil de 2 a 3 años antes de volverse obsoleto. INVU está diseñado para crecer con el negocio, extendiendo su vida útil a más de 10 años sin necesidad de migrar. El retorno de inversión se produce a través del ahorro de tiempo, reducción de errores, incremento en ventas y control financiero.', '"Un sistema básico te dura 2-3 años. INVU te dura 10 años o más porque crece contigo. El ROI se calcula en ahorro de tiempo, reducción de errores, incremento en ventas y control financiero. Si INVU te ayuda a reducir mermas en un 2%, eso son S/1,000 mensuales de ahorro en un restaurante de S/50,000. La inversión se paga sola."', 41),
('Las Preguntas de Diagnóstico para LATAM', 'El vendedor debe hacer preguntas de diagnóstico adaptadas al contexto latinoamericano: número de locales y países, sistemas actuales, presencia en delivery y ecommerce, volumen de ventas, área de producción, planes de autoservicio, presupuesto, desafíos operativos, y comparación con otras marcas. Estas preguntas revelan el dolor real y permiten dimensionar la solución.', 'En una reunión con un dueño de restaurante en Bogotá, el vendedor pregunta: "¿Cuántos locales tienes y en qué ciudades? ¿Qué sistema usas hoy? ¿Manejas delivery propio o solo apps? ¿Tienes ecommerce? ¿Qué tan importante es para ti la fidelización?" Con las respuestas, el vendedor sabe que el cliente necesita integración de delivery y ecommerce, y que la fidelización es clave. El diagnóstico guía toda la conversación.', 42),
('La Comparación con Datos en el Mercado Regional', 'El vendedor debe comparar INVU con las alternativas del mercado regional, pero con datos concretos. Explicar qué ofrecen los sistemas básicos, dónde fallan y por qué INVU es superior en integración, flexibilidad, soporte y costo a largo plazo. La comparación debe basarse en números, no en opiniones.', '"Los sistemas básicos te cobran S/250 de licencia POS, pero aparte te cobran S/120 de PSE externo y S/80 de soporte. Suma S/450 mensuales. INVU: S/350 mensuales todo incluido. Además, la competencia no tiene KDS, ni ecommerce, ni fidelización integrada. Cuando necesites esas herramientas, tendrás que comprar sistemas separados. INVU ya las tiene."', 43),
('El Framework Gravity Aplicado a LATAM', 'El Framework Gravity en el contexto latinoamericano se basa en 5 pasos: Diagnóstico (escuchar y entender la realidad del cliente), Educación (explicar la lógica del ecosistema integrado), Comparación (con datos concretos del mercado regional), Construcción de Valor (cuantificar beneficios), y Cierre (avanzar el proceso con confianza). Un cierre exitoso en LATAM se basa en la confianza y en haber demostrado que INVU entiende la realidad del cliente.', 'Un vendedor en Chile aplica Gravity: Diagnostica que el cliente tiene 3 locales y paga PSE externo. Educa sobre la FE nativa de INVU. Compara: "Tu costo actual es S/1,110/mes; con INVU es S/1,862/mes, pero incluye centralización y fidelización." Construye valor: "Si reduces mermas en un 2%, ahorras S/2,400/mes." Cierra: "¿Qué información necesitas para empezar la implementación?" El cliente confía y avanza.', 44)) AS t(concepto, enseñanza, ejemplo, orden);